using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var logger = sp.GetRequiredService<ILoggerFactory>();

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var researchTools = new ResearchTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agent = new ChatClientAgent(
    chatClient,
    id: "research-agent",
    name: "Research Agent",
    description: "Researches a topic by searching the web and taking notes, then summarizes findings.",
    tools: tools,
    loggerFactory: logger);

// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "quantum computing";
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var systemPrompt = $"""
    You are a research agent. Your goal is to thoroughly research the following topic
    and produce a well-organized summary.

    ## Instructions
    1. Use the SearchWeb tool to search for information about the topic.
       Make 2-4 searches with different queries to get diverse perspectives.
    2. Use the SaveNote tool to save important findings as you go.
    3. Use the GetNotes tool to review all your notes before writing the summary.
    4. Finally, produce a comprehensive summary with:
       - An overview of the topic
       - Key findings organized by theme
       - Sources referenced

    Topic: {topic}
    """;

var session = new AgentSession();
var response = await agent.RunAsync(
    [new ChatMessage(ChatRole.System, systemPrompt),
     new ChatMessage(ChatRole.User, $"Please research this topic: {topic}")],
    session,
    runOptions);

Console.WriteLine("── Research Summary ─────────────────────────────────");
Console.WriteLine();

var finalMessage = response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant);
Console.WriteLine(finalMessage?.Text ?? "No summary was generated.");

Console.WriteLine();
Console.WriteLine($"── Notes collected: {researchTools.NoteCount} ──");

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------
sealed class ResearchTools
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<string> _notes = [];

    public int NoteCount => _notes.Count;

    [Description("Searches the web for information on a query and returns a summary of results. " +
                 "Use this to find facts, articles, and data about a research topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        try
        {
            // Use Wikipedia's API as a free, no-key search source.
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search" +
                      $"&srsearch={encoded}&srlimit=4&format=json&utf8=1";

            var json = await s_http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();

            var index = 0;
            foreach (var item in results.EnumerateArray())
            {
                index++;
                var title = item.GetProperty("title").GetString();
                var snippet = item.GetProperty("snippet").GetString()
                    ?.Replace("<span class=\"searchmatch\">", "")
                    .Replace("</span>", "");

                sb.AppendLine($"{index}. **{title}**");
                sb.AppendLine($"   {snippet}");
                sb.AppendLine($"   Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
                sb.AppendLine();
            }

            if (index == 0)
            {
                sb.AppendLine("No results found.");
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Saves a research note for later reference. Use this to record key findings, " +
                 "facts, or quotes discovered during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note,
        [Description("A short category label (e.g. 'definition', 'history', 'statistics')")] string category)
    {
        var entry = $"[{category.ToUpperInvariant()}] {note}";
        _notes.Add(entry);
        Console.WriteLine($"  📝 Note saved ({category}): {Truncate(note, 60)}");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all research notes saved so far. " +
                 "Call this before writing your final summary to review collected information.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        Console.WriteLine($"  📋 Reviewing {_notes.Count} note(s)");
        var sb = new StringBuilder();
        sb.AppendLine($"All research notes ({_notes.Count}):");
        sb.AppendLine();

        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"  {i + 1}. {_notes[i]}");
        }

        return sb.ToString();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");
}

