using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Services
// ---------------------------------------------------------------------------
using var loggerFactory = LoggerFactory.Create(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

IChatClient chatClient = new OpenAIChatClient(
    new OpenAIClient(apiKey).GetChatClient(modelId));

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var researchTools = new ResearchTools();

var tools = new AITool[]
{
    AIFunctionFactory.Create(researchTools.SearchWebAsync),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var systemPrompt = """
    You are a research agent. Your goal is to thoroughly research a topic
    and produce a well-organized summary.

    ## Instructions
    1. Use the SearchWebAsync tool to search for information about the topic.
       Make 2-4 searches with different queries to get diverse perspectives.
    2. Use the SaveNote tool to save important findings as you go.
    3. Use the GetNotes tool to review all your notes before writing the summary.
    4. Finally, produce a comprehensive summary with:
       - An overview of the topic
       - Key findings organized by theme
       - Sources referenced
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: systemPrompt,
    name: "Research Agent",
    description: "Researches a topic by searching the web and taking notes, then summarizes findings.",
    tools: tools,
    loggerFactory: loggerFactory);

// ---------------------------------------------------------------------------
// Run
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "quantum computing";
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Please research this topic: {topic}",
    session,
    runOptions);

Console.WriteLine("── Research Summary ─────────────────────────────────");
Console.WriteLine();
Console.WriteLine(response.Text ?? "No summary was generated.");
Console.WriteLine();
Console.WriteLine($"── Notes collected: {researchTools.NoteCount} ──");

