for f in g.glob('/home/runner/.nuget/packages/openai/*/lib/*/OpenAI.xml'):
    tree = ET.parse(f)
    root = tree.getroot()
    for m in root.iter('member'):
        name = m.get('name','')
        if name.startswith('M:') and 'IChatClient' in name:
            print(name[:300])
        if name.startswith('M:') and 'AsChatClient' in name:
            print(name[:300])
        if name.startswith('M:') and 'AsBuilder' in name:
            print(name[:300])
" 2>&1 | head -10

